begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.mc(t text) returns uuid language sql immutable as $$select md5('community-tests-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mc(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.mc(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-community@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.mc('org'),'Comunidade fictícia','community-test-org','active'),(pg_temp.mc('other'),'Ministério externo','community-test-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.mc('a'),pg_temp.mc('org'),'Igreja A','a','headquarters'),(pg_temp.mc('b'),pg_temp.mc('org'),'Igreja B','b','campus'),(pg_temp.mc('c'),pg_temp.mc('other'),'Outra igreja','c','headquarters');
insert into public.organization_memberships(organization_id,user_id,default_unit_id,role,status) select pg_temp.mc('org'),pg_temp.mc(t),pg_temp.mc('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,phone) select pg_temp.mc(t||'-person'),pg_temp.mc('org'),pg_temp.mc('a'),pg_temp.mc(t),t||' fictício','active','11999990000' from unnest(array['member','second'])t;
create function pg_temp.self(a text,id uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_community_self(pg_temp.mc('org'),pg_temp.mc('a'),a,id,v,d)$$;
create function pg_temp.admin(a text,id uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_community_admin(pg_temp.mc('org'),pg_temp.mc('a'),a,id,v,d)$$;
create function pg_temp.item(t text) returns uuid language sql security definer as $$select id from private.community_notes where nonce=t union all select id from private.community_prayers where nonce=t union all select id from private.community_testimonies where nonce=t union all select id from private.community_groups where nonce=t limit 1$$;
create function pg_temp.part() returns uuid language sql security definer as $$select id from private.community_participation where user_id=pg_temp.mc('member')$$;
select ok(not has_table_privilege('authenticated','private.community_notes','select'),'anotações sem leitura direta');
select ok(not has_table_privilege('anon','private.community_prayers','select'),'oração sem acesso público');
select ok(not has_function_privilege('anon','public.member_community_self(uuid,uuid,text,uuid,integer,jsonb,integer)','execute'),'visitante não envia');
select pg_temp.actor('unconfirmed');set local role authenticated;
select throws_ok($$select pg_temp.self('notes')$$,'42501',null,'email não confirmado recusado');
reset role;select pg_temp.actor('outside');set local role authenticated;
select throws_ok($$select pg_temp.self('notes')$$,'42501','community_denied','conta de outro ministério recusada');
reset role;select pg_temp.actor('member');set local role authenticated;
select lives_ok($$select pg_temp.self('prayer.create',null,null,'{"nonce":"prayer-no-contact","category":"Família","body":"Pedido fictício reservado para teste","allowContact":false}')$$,'envio de oração privada');
select lives_ok($$select pg_temp.self('prayer.create',null,null,'{"nonce":"prayer-no-contact","category":"Família","body":"Pedido fictício reservado para teste","allowContact":false}')$$,'repetição com nonce não duplica');
select is(jsonb_array_length(pg_temp.self('prayers')->'items'),1,'um único pedido');
select throws_ok($$select pg_temp.admin('prayers')$$,'42501','community_denied','membro não administra oração');
select throws_ok($$select pg_temp.self('testimony.create',null,null,'{"nonce":"testimony-unsafe","title":"Texto fictício","body":"Testemunho de teste reservado","category":"Família","consent":false,"showName":false}')$$,'22023','community_consent','sem autorização não publica');
select lives_ok($$select pg_temp.self('testimony.create',null,null,'{"nonce":"testimony-member","title":"Texto fictício","body":"Testemunho de teste reservado","category":"Família","consent":true,"showName":false}')$$,'testemunho enviado para revisão');
select lives_ok($$select pg_temp.self('note.create',null,null,'{"nonce":"note-member-test","title":"Anotação pessoal","body":"Conteúdo privado de teste"}')$$,'anotação criada');
select lives_ok($$select pg_temp.self('note.create',null,null,'{"nonce":"note-member-test","title":"Anotação pessoal","body":"Conteúdo privado de teste"}')$$,'repetição de anotação não duplica');
select is(jsonb_array_length(pg_temp.self('notes')->'items'),1,'uma anotação');
select lives_ok($$select pg_temp.self('note.edit',pg_temp.item('note-member-test'),1,'{"title":"Anotação editada","body":"Novo conteúdo privado de teste"}')$$,'editar anotação própria');
select throws_ok($$select pg_temp.self('note.edit',pg_temp.item('note-member-test'),1,'{"title":"Outro texto","body":"Sobrescrita"}')$$,'40001','community_changed','versão antiga não sobrescreve');
select lives_ok($$select pg_temp.self('note.archive',pg_temp.item('note-member-test'),2)$$,'arquivar recuperável');
select is(jsonb_array_length(pg_temp.self('notes')->'items'),0,'arquivada não aparece na lista ativa');
select is(jsonb_array_length(pg_temp.self('archived')->'items'),1,'arquivada aparece no histórico próprio');
select lives_ok($$select pg_temp.self('note.restore',pg_temp.item('note-member-test'),3)$$,'restaurar anotação');
reset role;set local role anon;
select is(jsonb_array_length(public.member_community_public(pg_temp.mc('org'),pg_temp.mc('a'),'testimonies')->'items'),0,'testemunho pendente não aparece para visitante');
select is(jsonb_array_length(public.member_community_public(pg_temp.mc('org'),pg_temp.mc('c'),'testimonies')->'items'),0,'outra organização não atravessa unidade');
reset role;select pg_temp.actor('second');set local role authenticated;
select is(jsonb_array_length(pg_temp.self('prayers')->'items'),0,'outra conta não vê pedidos');
select is(jsonb_array_length(pg_temp.self('notes')->'items'),0,'outra conta não vê anotações');
select throws_ok($$select pg_temp.self('note.edit',pg_temp.item('note-member-test'),4,'{"title":"Fraude","body":"Outro texto"}')$$,'42501','community_denied','outra conta não edita anotação');
select throws_ok($$select pg_temp.self('testimony.withdraw',pg_temp.item('testimony-member'),1)$$,'42501','community_denied','outra conta não retira testemunho');
reset role;select pg_temp.actor('owner');set local role authenticated;
select is((pg_temp.admin('prayers')->'items'->0->'phone')::text,'null','equipe não recebe telefone sem autorização');
select is(jsonb_array_length(pg_temp.self('notes')->'items'),0,'admin não lê anotações de membro');
select throws_ok($$select pg_temp.admin('notes')$$,'22023','invalid_community','nenhum endpoint administrativo de anotações');
select lives_ok($$select pg_temp.admin('prayer.review',pg_temp.item('prayer-no-contact'),1,'{"status":"care","reply":"Estamos acompanhando seu pedido fictício."}')$$,'equipe acompanha oração');
select throws_ok($$select pg_temp.admin('prayer.review',pg_temp.item('prayer-no-contact'),1,'{"status":"completed","reply":"Concluído"}')$$,'40001','community_changed','decisão antiga recusada');
select lives_ok($$select pg_temp.admin('testimony.review',pg_temp.item('testimony-member'),1,'{"status":"published","reason":""}')$$,'aprovar texto autorizado');
select lives_ok($$select pg_temp.admin('group.create',null,null,'{"nonce":"group-music-test","name":"Louvor fictício","description":"Grupo local fictício","kind":"ministry","active":true,"accepting":true}')$$,'criar ministério local');
reset role;set local role anon;
select is(public.member_community_public(pg_temp.mc('org'),pg_temp.mc('a'),'testimonies')->'items'->0->>'author','Membro da igreja','publicação preserva nome não autorizado');
select ok(not (public.member_community_public(pg_temp.mc('org'),pg_temp.mc('a'),'testimonies')->'items'->0 ? 'user_id'),'publicação não expõe ID da conta');
select is(jsonb_array_length(public.member_community_public(pg_temp.mc('org'),pg_temp.mc('b'),'groups')->'items'),0,'grupo não aparece em outra igreja');
reset role;select pg_temp.actor('member');set local role authenticated;
select lives_ok($$select pg_temp.self('group.request',pg_temp.item('group-music-test'))$$,'solicitar participação');
select lives_ok($$select pg_temp.self('group.request',pg_temp.item('group-music-test'))$$,'solicitação repetida idempotente');
select is(jsonb_array_length(pg_temp.self('groups')->'items'),1,'uma participação por conta e grupo');
select ok(exists(select 1 from jsonb_array_elements(public.member_agenda_self(pg_temp.mc('org'),'inbox',pg_temp.mc('a'))->'items')n where n->>'target'='prayers'),'decisão de oração chega à caixa de entrada');
select lives_ok($$select pg_temp.self('testimony.withdraw',pg_temp.item('testimony-member'),2)$$,'autor retira publicação');
reset role;set local role anon;
select is(jsonb_array_length(public.member_community_public(pg_temp.mc('org'),pg_temp.mc('a'),'testimonies')->'items'),0,'retirada remove publicação imediatamente');
reset role;select pg_temp.actor('owner');set local role authenticated;
select throws_ok($$select pg_temp.admin('testimony.review',pg_temp.item('testimony-member'),3,'{"status":"published","reason":""}')$$,'40001','community_changed','equipe não republica texto retirado');
select lives_ok($$select pg_temp.admin('participant.review',pg_temp.part(),1,'{"status":"approved","reason":""}')$$,'aprovar participação');
reset role;
select is((select role::text from public.organization_memberships where organization_id=pg_temp.mc('org') and user_id=pg_temp.mc('member')),'member','participação não concede papel administrativo');
select is((select unit_id from public.people where id=pg_temp.mc('member-person')),pg_temp.mc('a'),'participação não transfere cadastro');
select is((select count(*)::integer from private.community_participation where user_id=pg_temp.mc('member')),1,'não duplica participação');
select pg_temp.actor('member');set local role authenticated;
select lives_ok($$select pg_temp.self('group.leave',pg_temp.part(),2)$$,'membro encerra participação');
select lives_ok($$select pg_temp.self('prayer.cancel',pg_temp.item('prayer-no-contact'),2)$$,'autor cancela pedido em acompanhamento');
reset role;select pg_temp.actor('owner');set local role authenticated;
select throws_ok($$select pg_temp.admin('prayer.review',pg_temp.item('prayer-no-contact'),3,'{"status":"care","reply":""}')$$,'40001','community_changed','cancelamento impede novo acompanhamento');
reset role;
select ok(not exists(select 1 from public.audit_logs where organization_id=pg_temp.mc('org') and metadata::text like '%Conteúdo privado%'),'auditoria não contém anotações');
select * from finish();
rollback;
